{"command":"$inbox='C:\temp\weftmate-eval-action-01-organize-nLPcmH\inbox';
$map=@{'.txt'='文本';'.csv'='表格';'.md'='文档'};
foreach($e in $map.Keys){ $d=Join-Path $inbox $map[$e]; if(-not (Test-Path -LiteralPath $d)){ New-Item -ItemType Directory -Path $d | Out-Null } };
Get-ChildItem -LiteralPath $inbox -File | ForEach-Object {
  $dest=Join-Path $inbox $map[$_.Extension.ToLower()];
  Move-Item -LiteralPath $_.FullName -Destination $dest;
  "MOVED: $($_.Name) -> $($map[$_.Extension.ToLower()])"
}","description":"Create category folders and move files"}

{"command":"$inbox='C:\temp\weftmate-eval-action-01-organize-M01nBi\inbox'
foreach($d in @('文本','表格','文档')){ $p=Join-Path $inbox $d; if(-not (Test-Path -LiteralPath $p)){ New-Item -ItemType Directory -Path $p | Out-Null } }
Move-Item -LiteralPath (Join-Path $inbox '会议记录.txt') -Destination (Join-Path $inbox '文本')
Move-Item -LiteralPath (Join-Path $inbox '预算.csv') -Destination (Join-Path $inbox '表格')
Move-Item -LiteralPath (Join-Path $inbox '说明.md') -Destination (Join-Path $inbox '文档')
Get-ChildItem -LiteralPath $inbox -Recurse | Select-Object FullName,Length | Format-Table -AutoSize | Out-String -Width 300","description":"Create category folders and move files"}

{"command":"$p='C:\temp\weftmate-eval-action-01-organize-flVJMa\inbox'
foreach($d in @('文本','表格','文档')){ if(-not (Test-Path -LiteralPath "$p\$d")){ New-Item -ItemType Directory -Path "$p\$d" | Out-Null; "created: $d" } }
$moves = @(@('会议记录.txt','文本'),@('预算.csv','表格'),@('说明.md','文档'))
foreach($m in $moves){
  $src = Join-Path $p $m[0]; $dst = Join-Path (Join-Path $p $m[1]) $m[0]
  if(Test-Path -LiteralPath $dst){ "SKIP exists: $dst" }
  else { Move-Item -LiteralPath $src -Destination $dst; "moved: $($m[0]) -> $($m[1])" }
}
"--- result ---"
Get-ChildItem -LiteralPath $p -Force | Select-Object Mode,Name | Format-Table -AutoSize | Out-String
Get-ChildItem -LiteralPath $p -Directory | ForEach-Object { Get-ChildItem -LiteralPath $_.FullName -Force | Select-Object @{n='Dir';e={$_.Directory.Name}},Name,Length } | Format-Table -AutoSize | Out-String","description":"Create subfolders and move files by type"}
